bool EqualProjected(const std::vector<R::ProjectedVertex>& a,const std::vector<R::ProjectedVertex>& b){
 if(a.size()!=b.size())return false;for(size_t i=0;i<a.size();++i){const auto& x=a[i];const auto& y=b[i];if(x.x!=y.x||x.y!=y.y||x.depth!=y.depth||x.distance!=y.distance||x.nx!=y.nx||x.ny!=y.ny||x.nz!=y.nz||x.r!=y.r||x.g!=y.g||x.b!=y.b||x.a!=y.a||x.u!=y.u||x.v!=y.v)return false;}return true;
}
